package dev.gbppimentel.snapcompanion;
import android.content.Context;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33)
public class EdenRequestsCacheTest {
 private Context c;private EdenLinkStore link;private EdenRequests requests;private String id;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.getSharedPreferences("snap-eden",0).edit().clear().commit();c.getSharedPreferences("snap-requests",0).edit().clear().commit();link=new EdenLinkStore(c);link.publish("default","A".repeat(32),"b".repeat(64),new EdenPhotodex.Snapshot(Map.of(),0,0));requests=new EdenRequests(c);id=new JSONObject(new String(c.getAssets().open("request-map.json").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("requests").getJSONObject(0).getString("id");}
 private JSONObject row(int schema)throws Exception{return new JSONObject().put("schema",schema).put("user","A".repeat(32)).put("metadataHash","b".repeat(64)).put("received",new JSONArray(List.of(id))).put("completed",new JSONArray(List.of(id))).put("unmapped",0).put("at",1000);}
 private void put(JSONObject row){c.getSharedPreferences("snap-requests",0).edit().putString("default",row.toString()).commit();}
 @Test public void legacyReceiptCacheDoesNotPretendCompletionIsKnown()throws Exception{put(row(1));var saved=requests.snapshot("default");assertNotNull(saved);assertEquals(Set.of(id),saved.received());assertFalse(saved.completionKnown());assertTrue(saved.completed().isEmpty());}
 @Test public void currentSchemaPublishesCompletedSubsetAndRejectsImpossibleMembership()throws Exception{put(row(2));var saved=requests.snapshot("default");assertNotNull(saved);assertTrue(saved.completionKnown());assertEquals(Set.of(id),saved.completed());put(row(2).put("received",new JSONArray()));assertNull(requests.snapshot("default"));}
 @Test public void saveRevisionAndSourceChangesDoNotReuseOldCompletionFlags()throws Exception{put(row(2));assertNotNull(requests.snapshot("default"));link.publish("default","A".repeat(32),"c".repeat(64),new EdenPhotodex.Snapshot(Map.of(),0,0));assertNull(requests.snapshot("default"));assertTrue(c.getSharedPreferences("snap-requests",0).contains("default"));}
 @Test public void oldCompletionCachesDoNotInventRewardConditionsAndSchemaThreeValidatesTheSubset()throws Exception{put(row(2));assertFalse(requests.snapshot("default").rewardConditionsKnown());assertTrue(requests.snapshot("default").rewardReady().isEmpty());put(row(3).put("rewardReady",new JSONArray(List.of(id))));assertTrue(requests.snapshot("default").rewardConditionsKnown());assertEquals(Set.of(id),requests.snapshot("default").rewardReady());put(row(3).put("rewardReady",new JSONArray(List.of(id))).put("completed",new JSONArray()));assertNull(requests.snapshot("default"));assertTrue(c.getSharedPreferences("snap-requests",0).contains("default"));}
}
